using System;using System.IO;using System.Drawing;using System.Linq;using System.Reflection;using System.Windows.Forms;using CircuitoStudio;
class ShowcaseCaptureTests{
 static string dest;static void Snap(Form f,string name){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(5,5);Exception failure=null;using(var context=new ApplicationContext())using(var timer=new Timer{Interval=700}){timer.Tick+=(sender,args)=>{timer.Stop();try{using(var b=new Bitmap(f.ClientSize.Width,f.ClientSize.Height)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(f.PointToScreen(Point.Empty),Point.Empty,f.ClientSize);b.Save(Path.Combine(dest,name+".png"));}}catch(Exception ex){failure=ex;}finally{f.Hide();context.ExitThread();}};f.Show();timer.Start();Application.Run(context);}if(failure!=null)throw failure;}

 [STAThread]static int Main(){try{Application.EnableVisualStyles();dest=Environment.GetEnvironmentVariable("OPENELETRIC_SCREENSHOTS");Directory.CreateDirectory(dest);var root=Environment.GetEnvironmentVariable("OPENELETRIC_ROOT");var flags=BindingFlags.NonPublic|BindingFlags.Instance;typeof(Studio).GetField("userData",BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,Path.Combine(Path.GetTempPath(),"openeletric-showcase-"+Guid.NewGuid().ToString("N")));var file=Path.Combine(root,"examples","industriais","01-bombeamento.circuito");var p=Project.Load(file);using(var main=new Studio()){main.Size=new Size(1580,1000);main.OpenProjectPath(file);Snap(main,"visao-geral");var tabs=(TabControl)typeof(Studio).GetField("tabs",flags).GetValue(main);tabs.SelectedIndex=2;Snap(main,"unifilar");tabs.SelectedIndex=3;Snap(main,"estudos");}using(var motor=new MotorStartingForm(p,p.Boards[0],p.Boards[0].Circuits[0])){motor.Size=new Size(1120,840);Snap(motor,"motor");}var network=Project.Load(Path.Combine(root,"examples","industriais","10-industria-tres-niveis.circuito"));using(var flow=new NetworkFlowForm(network,network.Boards[0].Circuits[0])){flow.Size=new Size(1500,920);Snap(flow,"fluxo-por-fase");}var enclosure=Project.Load(Environment.GetEnvironmentVariable("OPENELETRIC_ENCLOSURE_SAMPLE"));enclosure.Name="Quadro de distribuição — exemplo";using(var front=new EnclosureCatalogForm(enclosure,enclosure.Boards[0])){front.Size=new Size(1450,920);Snap(front,"frontal");}using(var report=new ReportSelectionForm(p)){report.Size=new Size(1450,920);Snap(report,"relatorios");}Console.WriteLine("PASS 7 real interface captures");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
